146	// registryGETContext is registryGET bound to ctx.
147	func registryGETContext(ctx context.Context, rawURL, username, password, token string) (body []byte, link, usedToken string, err error) {
148		resp, token, err := registryDoContext(ctx, http.MethodGet, rawURL, "", username, password, token)
149		if err != nil {
150			return nil, "", token, err
151		}
152		defer func() { _ = resp.Body.Close() }()
153		if resp.StatusCode != http.StatusOK {
154			return nil, "", token, &StatusError{Code: resp.StatusCode, Source: SourceRegistry}
155		}
156		body, err = io.ReadAll(io.LimitReader(resp.Body, maxTagResponse))
157		return body, resp.Header.Get("Link"), token, err
158	}
