197	// doRequestContext is doRequest bound to ctx; a context already done sends
198	// nothing.
199	func doRequestContext(ctx context.Context, method, rawURL, accept, username, password, token string) (*http.Response, error) {
200		req, err := http.NewRequestWithContext(ctx, method, rawURL, nil)
201		if err != nil {
202			return nil, buildRequestError("build request", rawURL, err)
203		}
204		if accept != "" {
205			req.Header.Set("Accept", accept)
206		}
207		switch {
208		case token != "":
209			req.Header.Set("Authorization", "Bearer "+token)
210		case username != "" && password != "":
211			req.SetBasicAuth(username, password)
212		}
213		resp, err := registryHTTPClient.Do(req)
214		if err != nil {
215			return nil, fmt.Errorf("%s %s: %w", method, RedactURL(rawURL), StripRedirectTarget(err))
216		}
217		return resp, nil
218	}
