264	// RegistryAPIBase is the v2 API root of a registry named in an image reference:
265	// Docker Hub has its own host, a local registry is reached over plain HTTP, and
266	// everything else over HTTPS. An empty registry is Docker Hub.
267	func RegistryAPIBase(registry string) string {
268		switch {
269		case registry == "":
270			return "https://registry-1.docker.io"
271		case strings.HasPrefix(registry, "localhost") || strings.HasPrefix(registry, "127.0.0.1"):
272			return "http://" + registry
273		}
274		return "https://" + registry
275	}
